css:
.v18 .v18-wrap { position: relative; max-width: 100%; color: var(--text); font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; font-size: 14px; line-height: 1.35; -webkit-text-size-adjust: 100%; }
.v18 * { box-sizing: border-box; min-width: 0; }
.v18 .v18-f, .v18 .v18-x { position: absolute; width: 0; height: 0; opacity: 0; pointer-events: none; }
.v18 .v18-head { padding: 2px 14px 10px; }
.v18 .v18-title { margin: 0; font-size: 19px; font-weight: 700; letter-spacing: -0.01em; line-height: 1.2; }
.v18 .v18-count { margin: 3px 0 0; font-size: 12.5px; color: var(--muted); font-variant-numeric: tabular-nums; }
.v18 .v18-strip { display: flex; gap: 3px; margin: 0 8px; padding: 3px; background: var(--surface); border: 1px solid var(--border); border-radius: 10px; }
.v18 .v18-tab { flex: 1 1 0; display: flex; align-items: center; justify-content: center; gap: 4px; padding: 7px 2px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--muted); cursor: pointer; user-select: none; white-space: nowrap; transition: background .12s, color .12s; }
.v18 .v18-tab b { font-weight: 700; font-variant-numeric: tabular-nums; color: var(--text); }
.v18 .v18-tab:hover { background: var(--surface2); }
.v18 .v18-t-all:hover { color: var(--text); }
.v18 .v18-f-all:checked ~ .v18-strip .v18-t-all, .v18 .v18-f-ath:checked ~ .v18-strip .v18-t-ath, .v18 .v18-f-tb:checked ~ .v18-strip .v18-t-tb, .v18 .v18-f-over:checked ~ .v18-strip .v18-t-over, .v18 .v18-f-under:checked ~ .v18-strip .v18-t-under { background: var(--surface2); box-shadow: inset 0 0 0 1px var(--border), 0 1px 0 rgba(59,130,246,.55); }
.v18 .v18-f-all:checked ~ .v18-strip .v18-t-all { color: var(--text); }
.v18 .v18-strip .v18-t-ath, .v18 .v18-strip .v18-t-ath b { color: var(--team-away-ink); }
.v18 .v18-strip .v18-t-tb, .v18 .v18-strip .v18-t-tb b { color: var(--team-home-ink); }
.v18 .v18-strip .v18-t-over, .v18 .v18-strip .v18-t-over b { color: var(--over-ink); }
.v18 .v18-strip .v18-t-under, .v18 .v18-strip .v18-t-under b { color: var(--under-ink); }
.v18 .v18-f:focus-visible ~ .v18-strip { outline: 2px solid var(--accent); outline-offset: 2px; }
.v18 .v18-list { list-style: none; margin: 8px 0 0; padding: 0; background: var(--surface); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); overflow: hidden; position: relative; }
.v18 .v18-x:not(:checked) ~ .v18-list { max-height: 322px; }
.v18 .v18-x:not(:checked) ~ .v18-list::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 44px; background: linear-gradient(rgba(23,27,36,0), var(--surface)); pointer-events: none; }
.v18 .v18-x:checked ~ .v18-list { max-height: 536px; overflow-y: auto; -webkit-overflow-scrolling: touch; overscroll-behavior: contain; }
.v18 .v18-up { display: inline-block; width: 9px; height: 9px; border-left: 2px solid var(--accent); border-top: 2px solid var(--accent); transform: rotate(45deg) translateY(3px); }
.v18 .v18-row { display: block; box-shadow: 0 -1px 0 var(--border); }
.v18 .v18-link { display: flex; align-items: center; gap: 8px; padding: 10px 12px 10px 14px; color: inherit; text-decoration: none; -webkit-tap-highlight-color: rgba(59,130,246,.12); transition: background .12s; }
.v18 .v18-link:hover { background: var(--surface2); }
.v18 .v18-link:active { background: rgba(59,130,246,.10); }
.v18 .v18-link:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.v18 .v18-disc { flex: 0 0 28px; width: 28px; height: 28px; border-radius: 50%; background: var(--surface2); box-shadow: 0 0 0 1px var(--border); display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 700; letter-spacing: .02em; color: var(--text); }
.v18 .v18-main { flex: 1 1 auto; display: flex; flex-direction: column; gap: 2px; }
.v18 .v18-ident { display: flex; flex-wrap: nowrap; align-items: center; gap: 0 5px; }
.v18 .v18-name { flex: 0 1 auto; font-weight: 600; font-size: 15px; line-height: 1.25; white-space: nowrap; }
.v18 .v18-name-sm { font-size: 13px; }
.v18 .v18-chev { flex: 0 0 auto; display: block; width: 7px; height: 7px; margin-left: 2px; border-right: 1.5px solid var(--muted); border-bottom: 1.5px solid var(--muted); transform: rotate(-45deg); opacity: .8; }
.v18 .v18-link:hover .v18-name { color: var(--accent); }
.v18 .v18-link:hover .v18-chev { border-color: var(--accent); opacity: 1; }
.v18 .src { flex: 0 0 auto; flex-shrink: 0; display: inline-block; font-size: 9.5px; font-weight: 600; line-height: 1.3; letter-spacing: .02em; color: var(--muted); background: var(--surface2); border: 1px solid var(--border); border-radius: 4px; padding: 1px 5px; white-space: nowrap; }
.v18 .v18-met { display: flex; flex-wrap: wrap; align-items: center; gap: 2px 7px; font-size: 12.5px; font-variant-numeric: tabular-nums; color: var(--muted); }
.v18 .v18-rec { color: var(--text); font-weight: 600; }
.v18 .v18-money { font-weight: 700; }
.v18 .v18-pos { color: var(--green); }
.v18 .v18-neg { color: var(--red); }
.v18 .v18-roi { font-weight: 500; opacity: .9; }
.v18 .stk, .v18 .v18-chip { display: inline-flex; align-items: center; gap: 3px; font-size: 9.5px; font-weight: 600; line-height: 1; padding: 3px 5px; border-radius: 999px; border: 1px solid var(--border); background: var(--surface2); color: var(--muted); white-space: nowrap; font-variant-numeric: tabular-nums; }
.v18 .sb { display: inline-flex; align-items: center; gap: 2px; font-size: 9.5px; font-weight: 600; line-height: 1; padding: 3px 6px; border-radius: 999px; border: 1px solid var(--border); background: var(--surface2); color: var(--muted); white-space: nowrap; font-variant-numeric: tabular-nums; }
.v18 .sb b { font-weight: 700; }
.v18 .sb .pos, .v18 .sb .w { color: var(--green); }
.v18 .sb .neg, .v18 .sb .l { color: var(--red); }
.v18 .sb .t { color: var(--gold); }
.v18 .v18-sub { display: flex; flex-wrap: wrap; align-items: center; gap: 3px 6px; font-size: 10.5px; color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.v18 .v18-pick { flex: 0 0 96px; width: 96px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px; text-align: center; }
.v18 .pk { display: inline-block; max-width: 100%; padding: 4px 6px; border-radius: 6px; background: var(--surface2); border: 1px solid var(--border); color: var(--text); font-size: 12.5px; font-weight: 700; line-height: 1.2; font-variant-numeric: tabular-nums; white-space: nowrap; }
.v18 .v18-price { display: flex; align-items: center; justify-content: center; min-height: 24px; max-width: 100%; font-size: 10px; line-height: 1.2; color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.v18 .v18-f-ath:checked ~ .v18-list .v18-row:not(.v18-s-ath), .v18 .v18-f-tb:checked ~ .v18-list .v18-row:not(.v18-s-tb), .v18 .v18-f-over:checked ~ .v18-list .v18-row:not(.v18-s-over), .v18 .v18-f-under:checked ~ .v18-list .v18-row:not(.v18-s-under) { display: none; }

.v18 .v18-more { display: none; margin: -1px 0 0; padding: 10px 14px; align-items: center; justify-content: center; font-size: 12.5px; font-weight: 600; color: var(--accent); background: var(--surface); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); cursor: pointer; user-select: none; -webkit-tap-highlight-color: rgba(59,130,246,.12); }
.v18 .v18-more:hover { background: var(--surface2); }
.v18 .v18-f-all:checked ~ .v18-more { display: flex; }
.v18 .v18-x:checked ~ .v18-more .v18-more-a, .v18 .v18-x:not(:checked) ~ .v18-more .v18-more-b { display: none; }
.v18 .v18-x:focus-visible ~ .v18-more { outline: 2px solid var(--accent); outline-offset: -2px; }
.v18 .v18-foot { display: flex; justify-content: flex-end; padding: 8px 14px 2px; }
.v18 .v18-info { width: 100%; }
.v18 .v18-info summary { display: flex; align-items: center; justify-content: center; width: 26px; height: 26px; margin-left: auto; border-radius: 50%; border: 1px solid var(--border); background: var(--surface); color: var(--muted); font-family: inherit; font-style: normal; font-size: 12px; font-weight: 700; line-height: 1; cursor: pointer; user-select: none; list-style: none; }
.v18 .v18-info summary::-webkit-details-marker { display: none; }
.v18 .v18-info summary:hover, .v18 .v18-info[open] summary { color: var(--text); border-color: var(--muted); }
.v18 .v18-info summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.v18 .v18-info p { margin: 8px 0 0; font-size: 11.5px; line-height: 1.45; color: var(--muted); font-variant-numeric: tabular-nums; white-space: normal; }
@media (min-width: 560px) { .v18 .v18-pick { flex-basis: 120px; width: 120px; } .v18 .v18-strip { margin: 0 14px; } }
